{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01RH1axB41iV1n3uZonJpCT7","type":"tool_result","content":"{\"result\":\"{\\\"success\\\": true, \\\"data\\\": {\\\"stdout\\\": \\\"#!/usr/bin/env python3\\\\n\\\\\\\"\\\\\\\"\\\\\\\"D027 unified preset evaluation script.\\\\n\\\\nComputes ToF (Turn of Flip), NoF (No Flip), SYCONScore on calibration data.\\\\nSupports base models and LoRA-adapted models. Uses NLI-based classification\\\\n(cross-encoder/nli-deberta-v3-base) with dynamic label mapping.\\\\n\\\\nGPU selection: use CUDA_VISIBLE_DEVICES=X environment variable prefix.\\\\n\\\\nDependencies: torch, transformers, peft (if --lora_path used)\\\\n\\\\nUsage:\\\\n  CUDA_VISIBLE_DEVICES=0 HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1 \\\\\\\\\\\\n  /root/miniconda3/bin/python eval_unified_preset.py \\\\\\\\\\\\n    --model_path /root/autodl-tmp/.hf_cache/Qwen/Qwen3-8B \\\\\\\\\\\\n    --data_path /root/contrastive_entrain_calib/data/calibration_v2_1_expanded.jsonl \\\\\\\\\\\\n    --output_dir /root/contrastive_entrain_calib/results/ \\\\\\\\\\\\n    --exp_id exp001_baseline\\\\n\\\\n  # With LoRA adapter:\\\\n  /root/miniconda3/bin/python eval_unified_preset.py \\\\\\\\\\\\n    --model_path /root/autodl-tmp/.hf_cache/Qwen/Qwen3-8B \\\\\\\\\\\\n    --lora_path /root/contrastive_entrain_calib/checkpoints/exp014/checkpoint-3000 \\\\\\\\\\\\n    --exp_id exp014_ckpt3000\\\\n\\\\\\\"\\\\\\\"\\\\\\\"\\\\nimport argparse\\\\nimport json\\\\nimport logging\\\\nimport os\\\\nimport re\\\\nimport sys\\\\nimport time\\\\nfrom pathlib import Path\\\\n\\\\nimport torch\\\\nfrom transformers import AutoModelForCausalLM, AutoModelForSequenceClassification, AutoTokenizer\\\\n\\\\nsys.path.insert(0, str(Path(__file__).resolve().parent))\\\\nfrom nli_utils import get_entailment_idx, get_contradiction_idx\\\\n\\\\nos.environ.setdefault(\\\\\\\"HF_HUB_OFFLINE\\\\\\\", \\\\\\\"1\\\\\\\")\\\\nos.environ.setdefault(\\\\\\\"TRANSFORMERS_OFFLINE\\\\\\\", \\\\\\\"1\\\\\\\")\\\\n\\\\nlogging.basicConfig(\\\\n    level=logging.INFO,\\\\n    format=\\\\\\\"%(asctime)s [%(levelname)s] %(name)s: %(message)s\\\\\\\",\\\\n)\\\\nlogger = logging.getLogger(\\\\\\\"eval_unified_preset\\\\\\\")\\\\n\\\\nNLI_MODEL_NAME = \\\\\\\"cross-encoder/nli-deberta-v3-base\\\\\\\"\\\\nDEFAULT_DATA = \\\\\\\"/root/contrastive_entrain_calib/data/calibration_v2_1_expanded.jsonl\\\\\\\"\\\\n\\\\n\\\\ndef parse_args():\\\\n    p = argparse.ArgumentParser(\\\\n        description=\\\\\\\"D027 unified preset eval: ToF / NoF / SYCONScore\\\\\\\"\\\\n    )\\\\n    p.add_argument(\\\\\\\"--model_path\\\\\\\", type=str, required=True,\\\\n                    help=\\\\\\\"Base model path (local dir or HF cache)\\\\\\\")\\\\n    p.add_argument(\\\\\\\"--lora_path\\\\\\\", type=str, default=None,\\\\n                    help=\\\\\\\"Optional LoRA adapter path\\\\\\\")\\\\n    p.add_argument(\\\\\\\"--data_path\\\\\\\", type=str, default=DEFAULT_DATA,\\\\n                    help=\\\\\\\"Calibration eval data (JSONL)\\\\\\\")\\\\n    p.add_argument(\\\\\\\"--output_dir\\\\\\\", type=str, default=\\\\\\\"./results\\\\\\\",\\\\n                    help=\\\\\\\"Directory for output files\\\\\\\")\\\\n    p.add_argument(\\\\\\\"--exp_id\\\\\\\", type=str, default=\\\\\\\"default\\\\\\\",\\\\n                    help=\\\\\\\"Experiment ID (used in output filenames)\\\\\\\")\\\\n    p.add_argument(\\\\\\\"--batch_size\\\\\\\", type=int, default=1,\\\\n                    help=\\\\\\\"Batch size for generation (currently single-sample)\\\\\\\")\\\\n    p.add_argument(\\\\\\\"--max_new_tokens\\\\\\\", type=int, default=512,\\\\n                    help=\\\\\\\"Max new tokens per generation\\\\\\\")\\\\n    return p.parse_args()\\\\n\\\\n\\\\ndef generate_response(model, tokenizer, messages, max_new_tokens=512):\\\\n    if hasattr(tokenizer, \\\\\\\"apply_chat_template\\\\\\\"):\\\\n        try:\\\\n            prompt_text = tokenizer.apply_chat_template(\\\\n                mes